//! The Objective-C runtime table and every `objc_msgSend` cast this repository
//! uses.
//!
//! `objc_msgSend` is not a variadic function in the C sense on Apple platforms:
//! each call site must cast it to the exact signature of the selector it sends.
//! Every such cast lives in this module, one newtype per selector, generated by
//! the `sel` macro, so a reviewer can audit the signatures in one place.

use std::ffi::{c_char, c_void, CStr};

use crate::error::{cstr, Result};

/// An Objective-C object handle.
pub type Id = *mut c_void;

/// A registered Objective-C selector.
pub type Sel = *const c_void;

/// The Objective-C runtime entry points, resolved from `libobjc`.
#[derive(Debug, Clone, Copy)]
pub struct Objc {
    /// `objc_getClass`.
    pub get_class: unsafe extern "C" fn(*const c_char) -> Id,
    /// `sel_registerName`.
    pub sel_register_name: unsafe extern "C" fn(*const c_char) -> Sel,
    /// `objc_msgSend`, cast per selector by the `sel` macro.
    pub msg_send: *mut c_void,
    /// `objc_retain`.
    pub retain: unsafe extern "C" fn(Id) -> Id,
    /// `objc_release`.
    pub release: unsafe extern "C" fn(Id),
    /// `objc_autoreleasePoolPush`.
    pub autorelease_pool_push: unsafe extern "C" fn() -> *mut c_void,
    /// `objc_autoreleasePoolPop`.
    pub autorelease_pool_pop: unsafe extern "C" fn(*mut c_void),
}

impl Objc {
    /// Register `name` as a selector.
    ///
    /// # Errors
    ///
    /// [`crate::Error::InvalidName`] when `name` is not NUL-terminated, or when the
    /// runtime refuses to register the selector.
    pub fn sel(&self, name: &'static [u8]) -> Result<Sel> {
        let name = cstr(name)?;
        // SAFETY: `name` is NUL-terminated and owned by the loader for the life
        // of the process; `sel_registerName` keeps its own copy.
        let sel = unsafe { (self.sel_register_name)(name.as_ptr()) };
        if sel.is_null() {
            return Err(crate::error::Error::invalid_name(name.to_bytes()));
        }
        Ok(sel)
    }

    /// Look up a class by name, or `None` when its image is not loaded.
    pub fn class(&self, name: &str) -> Option<Id> {
        let name = std::ffi::CString::new(name).ok()?;
        // SAFETY: `name` is NUL-terminated and lives for the call.
        let class = unsafe { (self.get_class)(name.as_ptr()) };
        (!class.is_null()).then_some(class)
    }

    /// Take a reference to `object`.
    ///
    /// # Safety
    ///
    /// `object` must be a live Objective-C object; every retain needs one release.
    pub unsafe fn retain(&self, object: Id) -> Id {
        // SAFETY: the caller guarantees a live object.
        unsafe { (self.retain)(object) }
    }

    /// Drop a reference to `object`.
    ///
    /// # Safety
    ///
    /// `object` must hold a reference taken by [`Objc::retain`] or returned with a
    /// `+1` convention, and must not be used afterwards.
    pub unsafe fn release(&self, object: Id) {
        // SAFETY: the caller guarantees a live, owned object.
        unsafe { (self.release)(object) }
    }
}

/// An autorelease pool for one scope.
///
/// Objective-C methods that return objects without a `new`/`alloc` prefix put
/// them in the calling thread's pool. A runtime that calls such a method in a
/// loop must push and pop a pool per call or the thread accumulates autoreleased
/// objects until the process ends.
pub struct Pool {
    objc: Objc,
    token: *mut c_void,
}

impl Pool {
    /// Push a pool for the current thread.
    pub fn push(objc: Objc) -> Self {
        // SAFETY: `objc_autoreleasePoolPush` has no preconditions beyond a live
        // runtime, which is what holding an `Objc` table means.
        let token = unsafe { (objc.autorelease_pool_push)() };
        Self { objc, token }
    }
}

impl Drop for Pool {
    fn drop(&mut self) {
        // SAFETY: `token` came from this pool's push on this thread and is popped
        // exactly once.
        unsafe { (self.objc.autorelease_pool_pop)(self.token) };
    }
}

impl std::fmt::Debug for Pool {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Pool").finish_non_exhaustive()
    }
}

/// A three-dimensional size, matching `MTLSize`.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Size {
    /// Width, in threads or threadgroups.
    pub width: u64,
    /// Height.
    pub height: u64,
    /// Depth.
    pub depth: u64,
}

impl Size {
    /// A size with all three extents.
    pub const fn new(width: u64, height: u64, depth: u64) -> Self {
        Self {
            width,
            height,
            depth,
        }
    }
}

macro_rules! sel {
    ($(#[$doc:meta])* $name:ident($($arg:ident: $ty:ty),*) -> $ret:ty) => {
        $(#[$doc])*
        #[derive(Clone, Copy, Debug)]
        pub struct $name {
            sel: Sel,
            msg_send: *mut c_void,
        }

        impl $name {
            fn load(objc: &Objc, name: &'static [u8]) -> Result<Self> {
                Ok(Self {
                    sel: objc.sel(name)?,
                    msg_send: objc.msg_send,
                })
            }

            /// Send this selector to `receiver`.
            ///
            /// # Safety
            ///
            /// `receiver` must be a live object that responds to this selector,
            /// and every argument must be valid for the C signature recorded in
            /// this newtype. Returning a `+1` object means the caller owns a
            /// reference.
            pub unsafe fn send(self, receiver: Id $(, $arg: $ty)*) -> $ret {
                // SAFETY: Apple's ABI casts `objc_msgSend` per selector; the
                // caller proves the receiver/selector pairing and the argument
                // validity, and the type here is that selector's documented C
                // signature. No selector in this module returns a struct, so the
                // `objc_msgSend_stret` variant on x86_64 is never needed.
                let function: unsafe extern "C" fn(Id, Sel $(, $ty)*) -> $ret =
                    unsafe { std::mem::transmute(self.msg_send) };
                unsafe { function(receiver, self.sel $(, $arg)*) }
            }
        }
    };
}

sel! {
    /// `-[NSObject retain]`-free retain via a message send is not used; this list
    /// starts at the Metal objects the runtime touches.
    ///
    /// `id -[MTLDevice name]`, an autoreleased `NSString`.
    DeviceName() -> Id
}
sel! {
    /// `BOOL -[MTLDevice hasUnifiedMemory]`.
    DeviceHasUnifiedMemory() -> u8
}
sel! {
    /// `NSUInteger -[MTLDevice maxBufferLength]`.
    DeviceMaxBufferLength() -> u64
}
sel! {
    /// `NSUInteger -[MTLDevice recommendedMaxWorkingSetSize]`.
    DeviceRecommendedMaxWorkingSet() -> u64
}
sel! {
    /// `BOOL -[MTLDevice supportsFamily:]`.
    DeviceSupportsFamily(family: i64) -> u8
}
sel! {
    /// `id<MTLCommandQueue> -[MTLDevice newCommandQueue]`.
    DeviceNewCommandQueue() -> Id
}
sel! {
    /// `id<MTLBuffer> -[MTLDevice newBufferWithLength:options:]`.
    DeviceNewBufferWithLength(length: u64, options: u64) -> Id
}
sel! {
    /// `id<MTLLibrary> -[MTLDevice newLibraryWithSource:options:error:]`.
    DeviceNewLibraryWithSource(source: Id, options: Id, error: *mut Id) -> Id
}
sel! {
    /// `id<MTLSharedEvent> -[MTLDevice newSharedEvent]`.
    DeviceNewSharedEvent() -> Id
}
sel! {
    /// `id<MTLComputePipelineState>
    /// -[MTLDevice newComputePipelineStateWithFunction:error:]`.
    DeviceNewComputePipelineState(function: Id, error: *mut Id) -> Id
}
sel! {
    /// `void* -[MTLBuffer contents]`.
    BufferContents() -> *mut c_void
}
sel! {
    /// `NSUInteger -[MTLBuffer length]`.
    BufferLength() -> u64
}
sel! {
    /// `id<MTLFunction> -[MTLLibrary newFunctionWithName:]`.
    LibraryNewFunction(name: Id) -> Id
}
sel! {
    /// `id<MTLCommandBuffer> -[MTLCommandQueue commandBuffer]`.
    QueueCommandBuffer() -> Id
}
sel! {
    /// `id<MTLComputeCommandEncoder> -[MTLCommandBuffer computeCommandEncoder]`.
    CommandBufferComputeEncoder() -> Id
}
sel! {
    /// `void -[MTLCommandBuffer commit]`.
    CommandBufferCommit() -> ()
}
sel! {
    /// `NSError* -[MTLCommandBuffer error]`, valid until the buffer is released.
    CommandBufferError() -> Id
}
sel! {
    /// `void -[MTLCommandBuffer encodeSignalEvent:value:]`.
    CommandBufferEncodeSignal(event: Id, value: u64) -> ()
}
sel! {
    /// `void -[MTLComputeCommandEncoder setComputePipelineState:]`.
    EncoderSetPipeline(pipeline: Id) -> ()
}
sel! {
    /// `void -[MTLComputeCommandEncoder setBuffer:offset:atIndex:]`.
    EncoderSetBuffer(buffer: Id, offset: u64, index: u64) -> ()
}
sel! {
    /// `void -[MTLComputeCommandEncoder setBytes:length:atIndex:]`.
    EncoderSetBytes(bytes: *const c_void, length: u64, index: u64) -> ()
}
sel! {
    /// `void -[MTLComputeCommandEncoder
    /// dispatchThreadgroups:threadsPerThreadgroup:]`.
    EncoderDispatchThreadgroups(threadgroups: Size, threads: Size) -> ()
}
sel! {
    /// `void -[MTLComputeCommandEncoder endEncoding]`.
    EncoderEndEncoding() -> ()
}
sel! {
    /// `NSUInteger -[MTLComputePipelineState maxTotalThreadsPerThreadgroup]`.
    PipelineMaxThreads() -> u64
}
sel! {
    /// `uint64_t -[MTLSharedEvent signaledValue]`.
    SharedEventSignaledValue() -> u64
}
sel! {
    /// `const char* -[NSString UTF8String]`, borrowed for the string's lifetime.
    StringUtf8() -> *const c_char
}
sel! {
    /// `NSString* +[NSString stringWithUTF8String:]`, autoreleased.
    ClassStringWithUtf8(bytes: *const c_char) -> Id
}
sel! {
    /// `NSString* -[NSError localizedDescription]`.
    ErrorLocalizedDescription() -> Id
}

/// Every selector this repository sends, registered once per table.
#[derive(Debug, Clone, Copy)]
pub struct Selectors {
    /// `-[MTLDevice name]`.
    pub device_name: DeviceName,
    /// `-[MTLDevice hasUnifiedMemory]`.
    pub device_has_unified_memory: DeviceHasUnifiedMemory,
    /// `-[MTLDevice maxBufferLength]`.
    pub device_max_buffer_length: DeviceMaxBufferLength,
    /// `-[MTLDevice recommendedMaxWorkingSetSize]`.
    pub device_recommended_max_working_set: DeviceRecommendedMaxWorkingSet,
    /// `-[MTLDevice supportsFamily:]`.
    pub device_supports_family: DeviceSupportsFamily,
    /// `-[MTLDevice newCommandQueue]`.
    pub device_new_command_queue: DeviceNewCommandQueue,
    /// `-[MTLDevice newBufferWithLength:options:]`.
    pub device_new_buffer: DeviceNewBufferWithLength,
    /// `-[MTLDevice newLibraryWithSource:options:error:]`.
    pub device_new_library: DeviceNewLibraryWithSource,
    /// `-[MTLDevice newSharedEvent]`.
    pub device_new_shared_event: DeviceNewSharedEvent,
    /// `-[MTLDevice newComputePipelineStateWithFunction:error:]`.
    pub device_new_pipeline: DeviceNewComputePipelineState,
    /// `-[MTLBuffer contents]`.
    pub buffer_contents: BufferContents,
    /// `-[MTLBuffer length]`.
    pub buffer_length: BufferLength,
    /// `-[MTLLibrary newFunctionWithName:]`.
    pub library_new_function: LibraryNewFunction,
    /// `-[MTLCommandQueue commandBuffer]`.
    pub queue_command_buffer: QueueCommandBuffer,
    /// `-[MTLCommandBuffer computeCommandEncoder]`.
    pub command_buffer_compute_encoder: CommandBufferComputeEncoder,
    /// `-[MTLCommandBuffer commit]`.
    pub command_buffer_commit: CommandBufferCommit,
    /// `-[MTLCommandBuffer error]`.
    pub command_buffer_error: CommandBufferError,
    /// `-[MTLCommandBuffer encodeSignalEvent:value:]`.
    pub command_buffer_encode_signal: CommandBufferEncodeSignal,
    /// `-[MTLComputeCommandEncoder setComputePipelineState:]`.
    pub encoder_set_pipeline: EncoderSetPipeline,
    /// `-[MTLComputeCommandEncoder setBuffer:offset:atIndex:]`.
    pub encoder_set_buffer: EncoderSetBuffer,
    /// `-[MTLComputeCommandEncoder setBytes:length:atIndex:]`.
    pub encoder_set_bytes: EncoderSetBytes,
    /// `-[MTLComputeCommandEncoder dispatchThreadgroups:threadsPerThreadgroup:]`.
    pub encoder_dispatch_threadgroups: EncoderDispatchThreadgroups,
    /// `-[MTLComputeCommandEncoder endEncoding]`.
    pub encoder_end_encoding: EncoderEndEncoding,
    /// `-[MTLComputePipelineState maxTotalThreadsPerThreadgroup]`.
    pub pipeline_max_threads: PipelineMaxThreads,
    /// `-[MTLSharedEvent signaledValue]`.
    pub shared_event_signaled_value: SharedEventSignaledValue,
    /// `-[NSString UTF8String]`.
    pub string_utf8: StringUtf8,
    /// `+[NSString stringWithUTF8String:]`.
    pub class_string_with_utf8: ClassStringWithUtf8,
    /// `-[NSError localizedDescription]`.
    pub error_localized_description: ErrorLocalizedDescription,
}

impl Selectors {
    pub(crate) fn register(objc: &Objc) -> Result<Self> {
        Ok(Self {
            device_name: DeviceName::load(objc, b"name\0")?,
            device_has_unified_memory: DeviceHasUnifiedMemory::load(objc, b"hasUnifiedMemory\0")?,
            device_max_buffer_length: DeviceMaxBufferLength::load(objc, b"maxBufferLength\0")?,
            device_recommended_max_working_set: DeviceRecommendedMaxWorkingSet::load(
                objc,
                b"recommendedMaxWorkingSetSize\0",
            )?,
            device_supports_family: DeviceSupportsFamily::load(objc, b"supportsFamily:\0")?,
            device_new_command_queue: DeviceNewCommandQueue::load(objc, b"newCommandQueue\0")?,
            device_new_buffer: DeviceNewBufferWithLength::load(
                objc,
                b"newBufferWithLength:options:\0",
            )?,
            device_new_library: DeviceNewLibraryWithSource::load(
                objc,
                b"newLibraryWithSource:options:error:\0",
            )?,
            device_new_shared_event: DeviceNewSharedEvent::load(objc, b"newSharedEvent\0")?,
            device_new_pipeline: DeviceNewComputePipelineState::load(
                objc,
                b"newComputePipelineStateWithFunction:error:\0",
            )?,
            buffer_contents: BufferContents::load(objc, b"contents\0")?,
            buffer_length: BufferLength::load(objc, b"length\0")?,
            library_new_function: LibraryNewFunction::load(objc, b"newFunctionWithName:\0")?,
            queue_command_buffer: QueueCommandBuffer::load(objc, b"commandBuffer\0")?,
            command_buffer_compute_encoder: CommandBufferComputeEncoder::load(
                objc,
                b"computeCommandEncoder\0",
            )?,
            command_buffer_commit: CommandBufferCommit::load(objc, b"commit\0")?,
            command_buffer_error: CommandBufferError::load(objc, b"error\0")?,
            command_buffer_encode_signal: CommandBufferEncodeSignal::load(
                objc,
                b"encodeSignalEvent:value:\0",
            )?,
            encoder_set_pipeline: EncoderSetPipeline::load(objc, b"setComputePipelineState:\0")?,
            encoder_set_buffer: EncoderSetBuffer::load(objc, b"setBuffer:offset:atIndex:\0")?,
            encoder_set_bytes: EncoderSetBytes::load(objc, b"setBytes:length:atIndex:\0")?,
            encoder_dispatch_threadgroups: EncoderDispatchThreadgroups::load(
                objc,
                b"dispatchThreadgroups:threadsPerThreadgroup:\0",
            )?,
            encoder_end_encoding: EncoderEndEncoding::load(objc, b"endEncoding\0")?,
            pipeline_max_threads: PipelineMaxThreads::load(
                objc,
                b"maxTotalThreadsPerThreadgroup\0",
            )?,
            shared_event_signaled_value: SharedEventSignaledValue::load(objc, b"signaledValue\0")?,
            string_utf8: StringUtf8::load(objc, b"UTF8String\0")?,
            class_string_with_utf8: ClassStringWithUtf8::load(objc, b"stringWithUTF8String:\0")?,
            error_localized_description: ErrorLocalizedDescription::load(
                objc,
                b"localizedDescription\0",
            )?,
        })
    }
}

/// Read a `+0` UTF-8 string object. The object must outlive the call.
///
/// # Safety
///
/// `object` must be a live `NSString` and any pool it was autoreleased into must
/// still be open.
pub unsafe fn utf8_owned(selectors: &Selectors, object: Id) -> Option<String> {
    if object.is_null() {
        return None;
    }
    // SAFETY: the caller guarantees a live `NSString`.
    let bytes = unsafe { selectors.string_utf8.send(object) };
    if bytes.is_null() {
        return None;
    }
    // SAFETY: `UTF8String` returns a NUL-terminated buffer owned by the string,
    // which the caller keeps alive for the duration of this call.
    Some(
        unsafe { CStr::from_ptr(bytes) }
            .to_string_lossy()
            .into_owned(),
    )
}

/// Read an `NSError`'s detail string.
///
/// # Safety
///
/// `error` must be a live `NSError` or null, and its autorelease pool must be open.
pub unsafe fn error_detail(selectors: &Selectors, error: Id) -> Option<String> {
    if error.is_null() {
        return None;
    }
    // SAFETY: the caller guarantees a live `NSError`.
    let description = unsafe { selectors.error_localized_description.send(error) };
    // SAFETY: forwarded to `utf8_owned`, which only needs a live string.
    unsafe { utf8_owned(selectors, description) }
}

/// Check whether a `BOOL` value returned as a byte is true.
pub fn bool_value(value: u8) -> bool {
    value != 0
}
